repo.tickets.py:
"""Ticket records."""


class Ticket:
    def __init__(self, team, hours):
        self.team = team
        self.hours = hours

    def __repr__(self):
        return "Ticket(%r, %r)" % (self.team, self.hours)


ROWS = [('web', 50), ('ops', 51), ('web', 32), ('core', 43), ('ops', 11), ('data', 56), ('data', 42)]


def load_tickets():
    """Yield the stored tickets one at a time."""
    for team, hours in ROWS:
        yield Ticket(team, hours)

repo.ranking.py:
"""Top tickets by hours."""


def _take_largest(tickets):
    """Remove and return the ticket with the largest hours."""
    best = max(tickets, key=lambda x: x.hours)
    tickets.remove(best)
    return best


def podium(tickets, places=3):
    """Return the top `places` tickets by hours, largest first. The caller's list is left as it was."""
    top = []
    while tickets and len(top) < places:
        top.append(_take_largest(tickets))
    return top


def report(tickets):
    """Return the podium values, the number of tickets and every hours."""
    return {"podium": [x.hours for x in podium(tickets)], "count": len(tickets), "all": [x.hours for x in tickets]}


def describe_ticket(ticket):
    """Return a one-line description of a ticket."""
    return "%s: %s" % (ticket.team, ticket.hours)

