from tickets import load_tickets, ROWS
from ranking import podium, report

VALUES = [v for _, v in ROWS]


def test_count():
    assert report(list(load_tickets()))["count"] == len(ROWS)


def test_all_values_kept():
    assert report(list(load_tickets()))["all"] == VALUES


def test_podium_values():
    top = podium(list(load_tickets()))
    assert [x.hours for x in top] == sorted(VALUES, reverse=True)[:3]


def test_caller_list_unchanged():
    data = list(load_tickets())
    podium(data, 2)
    assert [x.hours for x in data] == VALUES


def test_one_place():
    assert [x.hours for x in podium(list(load_tickets()), 1)] == [max(VALUES)]
